neu "1.0"
module example
use ExampleDomain as domain
public variant State { num failed, string ready }
public State status = { tag: "ready", payload: "ok" }
public domain::Outcome choice = { tag: "success", payload: "complete" }
public domain::Request request = { selected: ref(choice) }
public List<State> states = [status, { tag: "failed", payload: 3 }]
